// 🔗 Fusion données - SOLUTION SIMPLE v7
// STRATÉGIE: Seulement input actuel + all inputs

const currentInput = $input.item;
const allInputs = $input.all();

console.log('📊 DEBUG:');
console.log('- Current input type:', typeof currentInput);
console.log('- All inputs count:', allInputs.length);
console.log('- Current JSON keys:', currentInput?.json ? Object.keys(currentInput.json) : 'null');
console.log('- Current binary keys:', currentInput?.binary ? Object.keys(currentInput.binary) : 'null');

// Parse OpenAI depuis input actuel
let aiTitle = 'Titre IA manquant';
let aiSubtitle = 'Sous-titre IA manquant';
let aiBody = 'Corps IA manquant';

if (currentInput?.json && Array.isArray(currentInput.json)) {
  const aiMessage = currentInput.json[0]?.message;
  if (aiMessage?.content) {
    const aiContent = aiMessage.content;
    console.log('🤖 AI CONTENT TROUVÉ:', aiContent.substring(0, 200));

    try {
      const cleanJson = aiContent
        .replace(/```json/g, '')
        .replace(/```/g, '')
        .trim();

      const parsed = JSON.parse(cleanJson);
      console.log('🤖 AI PARSED:', parsed);

      if (parsed.title) aiTitle = parsed.title;
      if (parsed.subtitle) aiSubtitle = parsed.subtitle;
      if (parsed.body) aiBody = parsed.body;

      console.log('✅ AI parsing SUCCESS');
    } catch (error) {
      console.log('❌ AI parsing FAILED:', error.message);
    }
  } else {
    console.log('❌ Pas de message.content dans input actuel');
  }
} else {
  console.log('❌ Input actuel pas un array');
}

// Récupération binaires depuis input actuel
const finalBinary = {};
let binaryFound = false;

console.log('📎 RECHERCHE BINAIRES:');
if (currentInput?.binary && Object.keys(currentInput.binary).length > 0) {
  Object.keys(currentInput.binary).forEach(key => {
    const binaryData = currentInput.binary[key];
    console.log(`📎 Binary [${key}]:`, {
      exists: !!binaryData,
      type: typeof binaryData,
      hasData: !!(binaryData?.data),
      hasId: !!(binaryData?.id)
    });

    if (binaryData && (binaryData.data || binaryData.id)) {
      finalBinary.images = binaryData;
      console.log(`✅ BINARY VALID: ${key} → images`);
      binaryFound = true;
    }
  });
} else {
  console.log('⚠️ Pas de binaires dans input actuel');
}

const result = {
  json: {
    contenu: 'Contenu depuis input OpenAI',
    subtitle: '',
    ai_title: aiTitle,
    ai_subtitle: aiSubtitle,
    ai_body: aiBody,
    debug: {
      current_input_found: !!currentInput,
      ai_array: Array.isArray(currentInput?.json),
      ai_message: !!(currentInput?.json?.[0]?.message?.content),
      binary_found: binaryFound,
      binary_count: Object.keys(finalBinary).length
    }
  },
  binary: finalBinary
};

console.log('🎯 RÉSULTAT:');
console.log('- AI Title:', result.json.ai_title);
console.log('- Binary count:', Object.keys(result.binary).length);

return result;

// 🔍 DEBUG COMPLET - Collecte tous les logs
const result = {
  webhook_output: null,
  openai_output: null,
  fusion_output: $input.item.json,
  flask_output: null,
  current_input: $input.item,
  timestamp: new Date().toISOString(),
  debug_summary: {
    workflow_status: 'Collecte des données...',
    issues: []
  }
};

// Tenter de récupérer les données des autres nœuds
try {
  // Récupération sécurisée des outputs précédents
  const allItems = $input.all();
  console.log('🔍 TOUS LES ITEMS:', allItems.length);

  allItems.forEach((item, index) => {
    console.log(`Item ${index}:`, {
      hasJson: !!item.json,
      hasBinary: !!item.binary,
      jsonKeys: item.json ? Object.keys(item.json) : [],
      binaryKeys: item.binary ? Object.keys(item.binary) : []
    });
  });

  result.all_items = allItems;

} catch (error) {
  console.log('❌ Erreur récupération:', error.message);
  result.debug_summary.issues.push('Erreur récupération: ' + error.message);
}

console.log('🔍 EXPORT COMPLET:', JSON.stringify(result, null, 2));

return result;

const debugData = $input.item.json;

// Analyse des données collectées
let analysis = {
  webhook_found: false,
  openai_found: false,
  images_found: false,
  ai_content_found: false,
  flask_success: false,
  issues: []
};

// Vérifier les données Flask
if (debugData.flask_output && debugData.flask_output.success) {
  analysis.flask_success = true;
} else {
  analysis.issues.push('Flask: pas de succès détecté');
}

// Vérifier les images
if (debugData.all_items) {
  debugData.all_items.forEach((item, index) => {
    if (item.binary && Object.keys(item.binary).length > 0) {
      analysis.images_found = true;
      console.log(`✅ Images trouvées dans item ${index}`);
    }
  });
}

if (!analysis.images_found) {
  analysis.issues.push('Images: non trouvées dans les items');
}

// Résultat final basé sur les données Flask
const flaskResult = debugData.fusion_output;
if (flaskResult && flaskResult.success) {
  return { 
    json: { 
      status: 'success', 
      project_id: flaskResult.project_id, 
      download_url: 'http://host.docker.internal:5003/api/download/' + flaskResult.project_id,
      message: '🎉 Document InDesign créé avec succès !',
      analysis: analysis,
      debug_data: debugData
    } 
  };
}

return { 
  json: { 
    status: 'analysis_complete', 
    analysis: analysis,
    debug_data: debugData,
    message: 'Debug terminé - vérifiez les issues'
  } 
};
